// bk-pb — generated from src/bk-pb-*.js by tools/merge.js. Edit the src files, then run: node tools/merge.js
// Personal Banker / Branch Manager. Format: [topic, question, answer, 'B'|'D', 'E'|'M'|'S'|'X', source, { t: top, f: [follow-up q, a] }]
QB["bk-pb"] = (QB["bk-pb"] || []).concat([
["Role", "What does a personal banker or branch manager do?", "**Why they ask:** the opening question.\n\n**Answer:**\n\"A personal banker helps customers with their financial needs — opening accounts, deposits and loans, advising on products that genuinely fit, and building relationships — while meeting sales and service goals and staying compliant. A branch manager adds running the branch: leading and coaching the team, hitting branch goals, service quality, operations, cash and compliance. Both balance genuinely serving customers with growing the business, and doing it compliantly.\"\n\nTip: Serve customers, grow the business, stay compliant.", "B", "E", null, {"t":1,"f":["Banker vs branch manager?","The banker serves customers directly; the manager also leads the team, runs operations and owns branch results."]}],
["Sales", "How do you sell banking products without being pushy?", "**Why they ask:** needs-based selling matters (and post-scandal, ethics).\n\n**Answer:**\n\"I start from the customer's actual needs — ask about their situation and goals — and recommend products that genuinely help them, explaining the real benefit. Selling someone something they don't need destroys trust and, after industry scandals, carries serious compliance risk. Done right, it's advising: the customer wins and the relationship (and the business) grows. I'd never open an account a customer didn't ask for or need.\"\n\nTip: Needs-based advising; never sell what isn't needed.", "D", "M", null, {"t":1,"f":["Why is needs-based selling especially important now?","After scandals like fake accounts, regulators and customers demand it — unneeded products are both unethical and a compliance violation."]}],
["Service", "How do you handle an upset customer?", "**Why they ask:** service skill.\n\n**Answer:**\n\"I listen fully and let them vent, empathize genuinely, apologize for the frustration, and focus on solving the problem — finding what I can do and doing it, or escalating if needed. I stay calm and don't take it personally. A well-handled complaint often builds more loyalty than if nothing had gone wrong, so I treat it as a chance to show we care, within what's fair and compliant.\"\n\nTip: Listen, empathize, solve; a good recovery builds loyalty.", "B", "E", null, {"f":["What if you can't give them what they want?","Explain honestly and clearly why, offer what I can do, and make sure they feel heard and respected even in a no."]}],
["Compliance", "What compliance matters in retail banking?", "**Why they ask:** high-risk area.\n\n**Answer:**\n\"KYC and identity verification when opening accounts, BSA/AML — watching for and reporting suspicious activity, Reg CC funds availability, truth-in-lending and savings disclosures, fair lending, privacy, and fraud prevention. I follow procedures exactly even when a customer is in a hurry, because these protect customers and the bank, and violations carry serious penalties. Compliance isn't bureaucracy — it prevents fraud, money laundering and harm.\"\n\nTip: KYC/AML, disclosures, fair lending, fraud prevention.", "D", "M", null, {"t":1,"f":["Why verify identity carefully even when the customer is rushing?","To prevent fraud and identity theft and meet legal KYC requirements — skipping it exposes the customer and the bank."]}],
["Fraud", "How do you spot and prevent fraud at the branch?", "**Why they ask:** branches are a fraud front line.\n\n**Answer:**\n\"I watch for red flags — unusual transactions, pressure or urgency, inconsistent ID, customers who seem coached or distressed (often elder fraud or scams), and structuring to avoid reporting. I verify carefully, ask questions, and escalate suspicious activity. Protecting a customer from a scam — like someone being talked into wiring money — is one of the most important things a banker does, even when the customer resists.\"\n\nTip: Watch for red flags; protect customers from scams, including elder fraud.", "D", "M", null, {"f":["How do you handle a customer being scammed into a wire?","Pause, ask questions, explain the scam warning signs, and involve fraud/management — protecting them even if they're insistent."]}],
["Leadership", "As a branch manager, how do you lead and coach your team?", "**Why they ask:** people leadership.\n\n**Answer:**\n\"I set clear goals and expectations, coach through observation and feedback rather than just directives, develop people's skills, recognize good work, and model the service and ethics I expect. I create an environment where the team wants to perform and serve customers well. A branch runs on its people, so developing and motivating them — not just managing numbers — drives results.\"\n\nTip: Coach and develop people; model the standard.", "B", "M", null, {"f":["How do you motivate a team to hit goals ethically?","Focus on genuinely serving customers' needs — ethical selling naturally produces results, and I never incentivize wrong behavior."]}],
["Goals", "How do you balance sales goals with doing right by customers?", "**Why they ask:** the central tension in banking.\n\n**Answer:**\n\"They align when you sell based on real needs — a customer who gets products that genuinely help comes back and refers others, which grows the business sustainably. I never let goal pressure push unneeded products or shortcuts; that creates compliance risk and destroys trust. If goals ever encouraged wrong behavior, I'd raise it. Sustainable results come from serving customers well, not gaming numbers.\"\n\nTip: Real-needs selling makes goals and ethics align.", "D", "M", null, {"t":1,"f":["What would you do if a goal encouraged unethical selling?","Raise it with leadership — bad incentives cause scandals; I won't hit numbers by harming customers or breaking rules."]}],
["Operations", "What operational responsibilities does a branch manager have?", "**Why they ask:** running the branch.\n\n**Answer:**\n\"Cash management and vault controls, dual control and reconciliation, security and safety, audit readiness, scheduling and staffing, and ensuring procedures are followed. Operational errors and control failures cause losses and fraud, so I take controls seriously — like segregation of duties so no one person controls a whole transaction. A smooth, well-controlled branch supports both service and safety.\"\n\nTip: Cash controls, dual control, audit readiness.", "B", "M", null, {"f":["Why is dual control important?","So no single employee can complete a sensitive transaction alone — it prevents theft and errors."]}],
["Behavioral", "Tell me about building a customer relationship that grew.", "**Why they ask:** relationship value.\n\n**Answer (example):**\n\"A customer came in just to cash a check. I took time to understand their situation, helped them set up the right accounts, and over time, as I genuinely helped with their goals, they moved more of their banking and a loan to us and referred family. Treating them as a person to help, not a sale, built a real relationship that grew naturally.\"\n\nTip: Show relationship built on genuine help, not a transaction.", "D", "M", null, {"f":["What made them trust you?","I focused on their needs and gave honest advice, even when it meant not selling something — trust followed."]}],
["Service", "How do you serve a diverse customer base well?", "**Why they ask:** inclusion and fit.\n\n**Answer:**\n\"I treat every customer with respect and patience regardless of background, language, or financial sophistication, explain things clearly without jargon or condescension, and adapt to their needs. Many people find banking intimidating, so being approachable and genuinely helpful matters. Good service means everyone feels welcome and understood, which builds loyalty across the whole community the branch serves.\"\n\nTip: Respect, patience, clear communication for everyone.", "B", "E", null, {"f":["How do you help a customer who's financially overwhelmed?","Listen without judgment, explain options clearly, and help them find a realistic path — empathy and practical help."]}],
["Closing", "Why retail banking?", "**Why they ask:** motivation.\n\n**Answer:**\n\"I like helping people with something that genuinely matters — their finances — building real relationships, and the mix of service, sales and (as a manager) leadership. It's people-centered work with clear impact on customers' lives and the branch's success, and I enjoy both sides.\"\n\nTip: People-centered, relationship-driven, clear impact.", "B", "E", null, {"f":["Where do you want to grow?","Toward branch management, lending, or a specialist role — retail banking opens several paths."]}]
]);

// Personal Banker / Branch Manager — part 2. Format: [topic, question, answer, 'B'|'D', 'E'|'M'|'S'|'X', source, { t: top, f: [follow-up q, a] }]
QB["bk-pb"] = (QB["bk-pb"] || []).concat([
["Products", "Walk me through the main deposit products and when each fits a customer.", "**Why they ask:** matching products to needs is the core of the banker role.\n\n**Answer:**\n\"Checking is for everyday transactions and access, savings for a cushion that stays liquid, a money market account for a higher rate on a larger balance with limited transactions, and a CD for money the customer won't need for a set term in exchange for a higher fixed rate. The fit comes from the customer's goal and timeline: an emergency fund belongs in savings, not a CD with an early-withdrawal penalty, while money earmarked for a purchase in two years might do better in a CD. I ask what the money is for before I recommend where it goes.\"\n\nTip: Checking for access, savings for liquid cushion, money market for higher-balance rate, CD for term money — fit to the goal and timeline.", "D", "E", null, {"t":1,"f":["Why not put an emergency fund in a CD?","A CD ties the money up and charges an early-withdrawal penalty, so an emergency fund — which must be reachable — belongs in liquid savings."]}],
["Products", "What's the difference between APR and APY, and why does it matter to a customer?", "**Why they ask:** customers routinely confuse these and good bankers explain clearly.\n\n**Answer:**\n\"APY — annual percentage yield — is what a customer earns on a deposit, and it includes the effect of compounding, so it's the honest comparison number for savings and CDs. APR — annual percentage rate — is the cost of borrowing and reflects interest plus certain fees, used for loans and credit cards. The practical point: when comparing where to save, compare APY to APY, not a stated nominal rate, because compounding frequency changes the real yield. And when borrowing, APR lets you compare the true cost across lenders. I make sure the customer is comparing the right apples to apples.\"\n\nTip: APY is earned yield (includes compounding) for deposits; APR is borrowing cost for loans — compare like to like.", "D", "E", null, {"f":["Why compare APY rather than the stated rate on a CD?","APY folds in compounding frequency, so two CDs with the same nominal rate but different compounding earn differently — APY is the true comparison."]}],
["Compliance", "What are KYC and CIP, and what do you do when opening a new account?", "**Why they ask:** account opening is a regulated process the banker owns.\n\n**Answer:**\n\"Know Your Customer and the Customer Identification Program require me to verify who the customer is before opening an account — valid government ID, name, date of birth, address, and a taxpayer ID — and to understand the nature of the account. It's not bureaucracy for its own sake: it's how the bank prevents fraud, identity theft, and the system being used for illicit money. So I verify identity properly, don't take shortcuts even when a customer is impatient, and flag anything that doesn't add up. Getting onboarding right protects the customer and the bank and starts the relationship on solid footing.\"\n\nTip: Verify identity (ID, DOB, address, TIN) and understand the account's purpose — it prevents fraud and meets the Customer Identification Program.", "D", "M", null, {"f":["What do you do if a customer's ID or information doesn't match?","Don't open the account on questionable information — verify further, follow the bank's procedure, and escalate rather than take a shortcut."]}],
["Compliance", "What is BSA/AML, and what would make you file or escalate a suspicious activity report?", "**Why they ask:** AML awareness is mandatory in banking.\n\n**Answer:**\n\"The Bank Secrecy Act and anti-money-laundering rules require banks to detect and report activity that may involve illicit funds. As a frontline banker I watch for red flags — structuring deposits just under reporting thresholds, transactions with no clear business purpose, a sudden pattern inconsistent with the customer's profile, or a customer evasive about the source of funds. I don't accuse or tip off the customer; I document what I observed and escalate through the bank's process so the AML team can evaluate and file a suspicious activity report if warranted. My job is accurate observation and escalation, not investigation.\"\n\nTip: Spot red flags (structuring, no clear purpose, out-of-profile activity), never tip off the customer, document and escalate to the AML team.", "D", "M", null, {"t":1,"f":["What is structuring?","Breaking a large transaction into smaller amounts to stay under reporting thresholds and avoid detection — itself a reportable red flag."]}],
["Lending", "What consumer lending products do you handle, and how do you match one to a customer?", "**Why they ask:** cross-selling credit responsibly is part of the role.\n\n**Answer:**\n\"At the branch level that's typically personal loans, auto loans, credit cards, and home equity lines or loans. Matching starts with the purpose and the customer's ability to repay: a HELOC can be sensible for a home renovation at a lower rate than a credit card, but it puts the house at risk, so it's wrong for discretionary spending. A fixed personal loan suits a one-time need with predictable payments; a card suits ongoing, repaid-monthly purchases, not carrying a balance. I steer customers toward the cheapest appropriate option for their need, not the one that earns the bank the most, because a loan they can't handle helps no one.\"\n\nTip: Match the product to purpose and repayment ability; a HELOC risks the home, so it's wrong for discretionary spending.", "D", "M", null, {"f":["Why not push the highest-earning credit product?","A loan the customer can't comfortably repay leads to default, hardship and lost trust — the cheapest appropriate option builds a lasting relationship."]}],
["Advice", "How do you help a customer understand and improve their credit score?", "**Why they ask:** credit guidance is a high-value service interaction.\n\n**Answer:**\n\"I explain the main drivers in plain terms: payment history is the biggest factor, then how much of their available credit they're using (utilization), the length of their history, new credit inquiries, and the mix of credit types. Practically, the highest-impact moves are paying on time every time and keeping utilization low — for example, keeping balances well under their limits rather than maxed out. I'm careful not to overpromise quick jumps, because scores move gradually, and I point them to their free credit reports to check for errors. It's advice that genuinely helps them, which is also how a bank earns loyalty.\"\n\nTip: Payment history and low utilization matter most; scores move gradually — give honest, actionable guidance and point to free reports.", "D", "M", null, {"f":["What's the fastest legitimate lever for most customers?","Lowering credit utilization by paying down balances and paying on time — both are high-impact and within the customer's control."]}],
["Service", "A customer is angry about an overdraft or monthly fee. How do you handle it?", "**Why they ask:** fee disputes are the most common branch friction point.\n\n**Answer:**\n\"I listen first and acknowledge the frustration rather than defending the fee reflexively. Then I look at the account: if it was a genuine one-off, a good customer, or partly our error, a courtesy waiver is often the right call and keeps a relationship worth far more than the fee. If it's a recurring pattern, I waive it this time if appropriate but also fix the cause — setting up alerts, overdraft protection, a better-fit account, or a conversation about cash flow — so we're solving the problem, not just refunding it. The goal is the customer leaving feeling helped, and not back next month with the same fee.\"\n\nTip: Listen, waive when it's fair or our error, then fix the root cause (alerts, overdraft protection, right account) — not just refund.", "D", "M", null, {"t":1,"f":["When would you not waive a fee?","When it's a repeated, properly disclosed charge the customer keeps incurring despite help — then the fix is solving the cause, not endless waivers."]}],
["Regulation", "What is FDIC insurance and how do you explain it to a worried customer?", "**Why they ask:** customers ask about safety, especially in uncertain times.\n\n**Answer:**\n\"FDIC insurance protects deposits at insured banks up to the standard limit — commonly 250,000 per depositor, per insured bank, per ownership category — so if the bank failed, insured deposits are protected up to that limit. I explain it plainly to reassure a worried customer, and for someone with more than the limit I show how ownership categories and account titling can extend coverage, or suggest spreading deposits across institutions. It's one of the genuinely reassuring facts in banking, and explaining it accurately builds trust rather than brushing off a real concern.\"\n\nTip: FDIC covers deposits up to the standard limit per depositor, per bank, per ownership category — titling and multiple banks can extend coverage.", "D", "E", null, {"f":["How can a customer protect balances above the limit?","Use different ownership categories, title accounts appropriately, or spread deposits across multiple insured banks so each stays within the limit."]}],
["Fraud", "How do you recognize and respond to a scam targeting an elderly customer?", "**Why they ask:** elder financial exploitation is a serious, frequent branch issue.\n\n**Answer:**\n\"I watch for the signs — an older customer suddenly withdrawing or wiring large sums, acting nervous or coached, mentioning a lottery, a grandchild in trouble, a 'government' demand, or a new person involved in their finances. When I see them, I slow the transaction down and ask gentle questions: who's it for, did someone contact you, can we verify this together. Scammers rely on urgency and secrecy, so creating a calm pause and a sanity check often breaks the spell. I follow the bank's escalation process for suspected exploitation. A few minutes of care can save someone's life savings.\"\n\nTip: Watch for urgency, secrecy and out-of-pattern large transfers; slow it down, ask gentle verifying questions, and escalate per policy.", "D", "M", null, {"t":1,"f":["Why does slowing the transaction down help?","Scams depend on urgency and secrecy — a calm pause and a few questions give the customer space to reconsider and often exposes the scam."]}],
["Regulation", "How do you handle a debit card dispute or unauthorized transaction?", "**Why they ask:** error resolution is a regulated, common service task.\n\n**Answer:**\n\"When a customer reports an unauthorized or erroneous electronic transaction, there's a defined error-resolution process under the rules governing electronic transfers — I take the details, document when they noticed it, open the dispute promptly, and explain the timeline and any provisional credit while it's investigated. Speed matters because consumer protections and liability can depend on how quickly the customer reports, so I don't let a report sit. I also help them protect the account — new card, changed credentials — and reassure them about the process. Handling a fraud scare calmly and correctly is a big trust moment.\"\n\nTip: Document and open the dispute promptly under the electronic-transfer error-resolution process, explain the timeline and provisional credit, and secure the account.", "D", "M", null, {"f":["Why does prompt reporting matter for the customer?","Consumer liability limits for unauthorized electronic transactions can depend on how quickly the customer reports, so speed protects them."]}],
["Goals", "How do you set and hit branch sales goals without pressuring customers into products they don't need?", "**Why they ask:** the industry learned hard lessons about toxic sales culture.\n\n**Answer:**\n\"I reframe goals as outcomes of good needs-based conversations, not quotas to force. When bankers genuinely uncover needs — a customer overpaying on a card who'd benefit from a consolidation loan, or someone with idle cash who should be earning more — the right products follow and the goals take care of themselves. I explicitly reward quality and retention, not just raw product counts, because incentives that reward opening accounts regardless of need produce fake or unwanted products and destroy trust. I'd rather miss a monthly number than build a book on products customers didn't want.\"\n\nTip: Hit goals through genuine needs-based conversations; reward quality and retention, never raw counts that incentivize unwanted products.", "D", "S", null, {"t":1,"f":["Why are count-based sales incentives dangerous?","They push staff to open accounts or products regardless of need, which leads to unwanted or fake accounts, regulatory trouble and destroyed customer trust."]}],
["Service", "What is a needs-based financial conversation and how do you run one?", "**Why they ask:** it's the skill that distinguishes a banker from an order-taker.\n\n**Answer:**\n\"It's a short, genuine conversation about the customer's situation and goals before any product comes up. I ask open questions — what they're saving for, how they're managing day to day, any big expenses coming, whether their money is working for them — and listen. Often I surface something they hadn't thought about: idle savings earning nothing, a high-interest balance worth consolidating, or no emergency fund. Only then do I connect a product to the need, and sometimes the right answer is advice with no product at all. Customers can tell the difference between being understood and being sold to.\"\n\nTip: Ask open questions about goals and situation, listen, then connect a product only to a real need — sometimes the answer is advice, not a sale.", "D", "M", null, {"f":["What if the best answer is no product?","Then I give the advice anyway — honesty when there's nothing to sell is exactly what earns the trust that brings the customer back when there is."]}],
["Operations", "How do cash handling controls like dual control and teller balancing work, and why do they matter?", "**Why they ask:** cash integrity is fundamental branch operations.\n\n**Answer:**\n\"Tellers balance their cash drawers against transactions each day so any discrepancy is caught immediately and near its source. Higher-value functions like the vault and large cash shipments use dual control — two people, so no single person can access or move cash alone. These controls protect both the bank and the employees: they deter and catch theft or error, and they clear honest staff from suspicion when something's off. As a manager I enforce them consistently, because the moment controls get sloppy 'to save time' is exactly when losses and fraud creep in.\"\n\nTip: Daily balancing catches discrepancies at the source; dual control stops any one person acting alone — consistent enforcement protects staff and bank.", "D", "M", null, {"f":["Why does dual control protect honest employees too?","With two people required, no individual can be solely blamed or solely able to steal — it clears the honest and deters the rest."]}],
["Service", "A customer is declined for a loan they expected to get. How do you deliver that?", "**Why they ask:** handling declines with empathy and accuracy matters.\n\n**Answer:**\n\"I deliver it honestly and with respect, explaining the general reason within what I'm permitted to disclose — and the customer is entitled to the required notice of the principal reasons for an adverse decision. I avoid making them feel judged; a decline is about the application meeting criteria, not their worth. Then I pivot to constructive help: what could change the outcome — paying down utilization, a co-signer, a secured option, building history — and a realistic path and timeline. Often I can offer a smaller or different product that fits now. People remember whether you treated them with dignity when the answer was no.\"\n\nTip: Explain the reason honestly and respectfully, provide the required adverse-action notice, and offer a constructive path or an alternative product.", "D", "M", null, {"f":["What is an adverse action notice?","A required disclosure giving the principal reasons credit was denied, so the applicant understands the decision and how they might improve it."]}],
["Strategy", "The branch's role is shrinking as customers go digital. How do you keep a branch relevant and growing?", "**Why they ask:** branch managers must adapt to the digital shift.\n\n**Answer:**\n\"Routine transactions have moved to the app, so the branch's value is now the things digital can't do well: complex needs conversations, advice, problem-solving a frustrated customer, small-business relationships, and major life moments like a home purchase or a fraud scare. I orient the team around those high-value interactions, help customers who want it get comfortable with digital tools so simple needs are self-served, and focus the branch on deepening relationships and local community presence. A branch that just processes transactions is obsolete; one that advises and solves problems is more valuable than ever.\"\n\nTip: Shift the branch from transactions to advice, problem-solving, small business and life-moment relationships digital can't replicate.", "D", "S", null, {"f":["What should the team spend less time on?","Routine transactions customers can self-serve — reallocating that time to advice, relationship-building and complex problem-solving."]}],
["Leadership", "How do you coach a teller or banker who is struggling to meet expectations?", "**Why they ask:** developing people is central to branch management.\n\n**Answer:**\n\"I start by diagnosing why — is it skill, confidence, clarity on expectations, or something outside work — because each needs a different response. Then I set specific, achievable goals, model the behavior, give frequent concrete feedback rather than waiting for a review, and pair them with a strong peer. I follow up consistently so they feel supported, not surveilled. Most people improve when expectations are clear and the help is real; if someone genuinely can't or won't after honest coaching, I address it fairly through the proper process. But I owe them a real chance to succeed first.\"\n\nTip: Diagnose the cause, set specific goals, give frequent concrete feedback and support — give a genuine chance before formal steps.", "D", "M", null, {"f":["What if coaching doesn't work?","Then I address it fairly through the proper performance process — but only after a genuine, documented effort to help them succeed first."]}],
["Operations", "How do you staff and schedule a branch to balance service and cost?", "**Why they ask:** practical management of the branch's biggest expense.\n\n**Answer:**\n\"I schedule to the traffic, not evenly across the day. Branches have predictable peaks — lunch hours, Fridays, the first and last of the month, paydays — so I put more staff on the floor then and lighter coverage in the lulls, while keeping dual-control and coverage minimums intact. I cross-train so people can flex between teller and banker roles as demand shifts, and I plan around lunches, breaks and time off so there's never a line with half the stations closed. Good scheduling means customers get served promptly without carrying idle labor cost in the quiet hours.\"\n\nTip: Schedule to predictable peaks (lunch, Fridays, month-end, paydays), cross-train for flexibility, and keep control minimums intact.", "D", "M", null, {"f":["Why cross-train branch staff?","So you can flex people between teller and banker work as demand shifts, covering peaks and absences without overstaffing the quiet hours."]}],
["Business", "How do you open and serve a small-business account well?", "**Why they ask:** small-business relationships are high-value for branches.\n\n**Answer:**\n\"Opening a business account needs the right documentation — formation documents, the business's tax ID, ownership and authorized-signer information, and beneficial-ownership details the rules require — so I get that right up front to avoid delays. Beyond opening, small-business owners value a banker who understands their cash flow: the right account to minimize fees, merchant services, a line of credit for seasonality, payroll and remote deposit. I treat them as a relationship, not a transaction, because a well-served small business brings deposits, lending, and the owner's personal banking too, and they refer other owners.\"\n\nTip: Get the entity documentation and beneficial-ownership right, then serve cash-flow needs (accounts, credit line, merchant services) as a relationship.", "D", "M", null, {"f":["Why is beneficial ownership information required?","Rules require banks to identify the individuals who own or control a legal-entity customer, to prevent anonymous shell companies being used for illicit finance."]}],
["Advice", "How would you advise a customer on using a CD ladder?", "**Why they ask:** a concrete, useful savings strategy a banker should know.\n\n**Answer:**\n\"A CD ladder splits money across CDs with staggered maturities instead of locking it all into one term. For example, rather than one 60,000 three-year CD, a customer could put 20,000 each into one-, two-, and three-year CDs. Every year one matures, giving access to some cash without penalty, and they can reinvest it at the then-current rate. It balances the higher yield of longer terms with regular liquidity and reduces the risk of locking everything in right before rates rise. I tailor the rungs to when the customer might need the money.\"\n\nTip: Stagger maturities so money frees up regularly and reinvests at current rates — balancing yield against liquidity.", "D", "M", null, {"f":["What problem does laddering solve versus one long CD?","It gives regular access to part of the money without penalty and spreads reinvestment across rate environments, instead of locking everything at one rate and date."]}],
["Fraud", "How do you help prevent a customer from falling victim to a wire transfer scam?", "**Why they ask:** wire fraud losses are large and often irreversible.\n\n**Answer:**\n\"Wires are fast and usually irreversible, so prevention at the counter is critical. When a customer requests a wire, especially a large or unusual one, I ask about the purpose: is it a home purchase where escrow details could have been spoofed, a 'relative in trouble,' an online romance, an investment that pressures speed? Red flags are urgency, a payee the customer has never met, and instructions received by email that changed at the last minute. I encourage them to independently verify the recipient through a known number, not the one provided, before we send. A short verification pause has saved customers from losing everything.\"\n\nTip: Ask the purpose, watch for urgency and last-minute changed instructions, and have the customer independently verify the recipient before sending an irreversible wire.", "D", "M", null, {"t":1,"f":["Why verify wire instructions through a known number?","Scammers spoof emails and change payment details at the last moment; confirming through an independently known contact catches the fraud before an irreversible transfer."]}]
]);

// Personal Banker / Branch Manager — part 3. Format: [topic, question, answer, 'B'|'D', 'E'|'M'|'S'|'X', source, { t: top, f: [follow-up q, a] }]
QB["bk-pb"] = (QB["bk-pb"] || []).concat([
["Service", "The lobby is backed up and customers are visibly frustrated. What do you do?", "**Why they ask:** real-time service recovery is a daily branch-manager test.\n\n**Answer:**\n\"I don't stand in my office watching a line build. I open another station, step onto the floor myself, and triage — quick transactions move fast, complex ones go to a banker's desk so they don't clog the teller line. I acknowledge the wait out loud, which defuses a lot of the frustration just by showing we see it. Afterward I look at why it happened — a staffing gap, a system issue, a predictable peak I under-scheduled — and fix the pattern so it's not a recurring experience. Customers forgive a one-off wait handled visibly; they leave over chronic ones ignored.\"\n\nTip: Open stations, get on the floor, triage quick vs complex, acknowledge the wait — then fix the root cause so it's not chronic.", "D", "M", null, {"t":1,"f":["How do you prevent recurring lobby backups?","Schedule to predictable peaks, cross-train so stations can open fast, and watch for system slowdowns — treat a chronic wait as a fixable pattern."]}],
["Strategy", "As branch manager, how do you grow deposits and loans in your branch?", "**Why they ask:** growth is the core accountability of the role.\n\n**Answer:**\n\"Growth comes from three places and I work all three. First, deepen existing relationships — most customers use a fraction of what they could, so proactive reviews surface deposit and lending needs already sitting in the book. Second, retention — a dollar kept is cheaper than a dollar won, so I protect at-risk relationships and fix service problems fast. Third, new acquisition through referrals, small-business outreach, and local presence. I set the team on quality conversations rather than chasing any number, track the leading activities, and celebrate deepened relationships, because sustainable growth is built on customers who want more from us, not pushed into it.\"\n\nTip: Deepen existing relationships, retain at-risk ones, and acquire via referrals and local presence — growth from quality conversations, not pushed quotas.", "D", "S", null, {"f":["Why prioritize deepening over new acquisition?","Existing customers are cheaper to grow and already trust you — most use only a fraction of what they could, so the easiest growth is already in the book."]}],
["Community", "How does local community involvement help a branch?", "**Why they ask:** branches are local businesses and community ties drive growth.\n\n**Answer:**\n\"A branch lives or dies on local relationships, so I invest in being genuinely present — financial-education sessions, small-business groups, local events, nonprofit involvement. It's not just goodwill: it's where small-business owners and future customers actually are, and being the banker who showed up and helped builds a referral engine no ad buy matches. People bank with people they know and trust, especially for the bigger moments like a mortgage or a business loan. I encourage the team to build these ties too, so the branch is woven into the community rather than just sitting on a corner.\"\n\nTip: Local presence — education, small-business groups, events — builds the trust and referrals that drive branch growth.", "B", "M", null, {"f":["How does community work translate into business?","It builds relationships with the people and small businesses who then bank with you and refer others — trust earned locally beats advertising for big decisions like mortgages."]}],
["Leadership", "How do you handle a disruptive or negative employee affecting branch morale?", "**Why they ask:** one bad attitude can poison a small team.\n\n**Answer:**\n\"I address it directly and privately, early, because negativity spreads fast in a small branch. I describe the specific behavior and its impact, listen for a root cause — sometimes it's a legitimate grievance I can fix — and set a clear expectation for change. I follow up, recognize improvement, and keep the rest of the team's standards high so one person's attitude doesn't become the norm. If the behavior continues despite honest feedback, I move to the formal process fairly and consistently. Protecting the team's culture is part of protecting the customers' experience.\"\n\nTip: Address it early and privately with specific behavior and impact, seek the cause, set expectations, and escalate fairly if it persists.", "D", "M", null, {"f":["Why act early on a negative attitude?","In a small team it spreads quickly and erodes morale and service — a quiet word early is far easier than undoing an entrenched culture problem."]}],
["Metrics", "How do you balance sales metrics with service quality metrics?", "**Why they ask:** the tension between selling and serving defines the role.\n\n**Answer:**\n\"I treat service quality as the leading indicator and sales as the lagging result, not the reverse. If the team runs great needs-based conversations and customers feel well served — which service and satisfaction scores capture — the sales outcomes follow and, crucially, stick. So I watch both but weight quality and retention, and I'm wary of any period where product numbers rise while satisfaction or complaint metrics worsen, because that's the fingerprint of pushing. The healthiest branch has strong numbers and strong loyalty together; sales bought at the cost of service are borrowed, not earned.\"\n\nTip: Service quality leads, sales follow — watch for rising product counts alongside falling satisfaction, the fingerprint of pushing.", "D", "S", null, {"f":["What pattern would worry you in the metrics?","Product sales climbing while satisfaction drops or complaints rise — a sign the team is pushing products rather than serving needs."]}],
["Compliance", "You suspect a customer is using accounts to launder money. What exactly do you do?", "**Why they ask:** correct AML handling in a live scenario.\n\n**Answer:**\n\"I stay calm and normal — I do not confront or tip off the customer, because that can itself be an offense and can destroy an investigation. I continue to serve them professionally while carefully documenting the specific facts I observed: the transactions, amounts, timing, and what makes them inconsistent with the customer's known profile. Then I escalate through the bank's defined channel to the AML or BSA team, who evaluate and decide on a suspicious activity report. My role is accurate observation, discretion, and timely escalation — not investigating, accusing, or making the filing decision myself.\"\n\nTip: Don't tip off or confront; serve normally, document specific facts, and escalate to the AML/BSA team to evaluate a report.", "D", "S", null, {"t":1,"f":["Why is tipping off the customer a serious problem?","It can be a legal offense and can compromise an investigation — the process depends on the customer not knowing they're under review."]}],
["Leadership", "How do you develop your bankers and build a succession bench?", "**Why they ask:** good managers grow people, not just numbers.\n\n**Answer:**\n\"I treat development as part of the job, not an afterthought. I give people stretch responsibilities — running a morning huddle, owning a product area, handling tougher customer situations with support — so they grow real skills before they're promoted. I'm candid about what each person needs to reach the next role and give them the reps to get there. Building a bench means my strong banker can step up when I'm out, and someone's ready when a role opens, so the branch isn't fragile. Developing people also retains them; the best ones leave when they stop growing.\"\n\nTip: Give stretch responsibilities and candid development paths — build a bench so the branch isn't fragile and strong people stay.", "D", "M", null, {"f":["Why does developing people improve retention?","Strong performers leave when they stop growing — giving them real development and a visible path keeps them engaged and loyal."]}],
["Behavioral", "Tell me about a time you improved an underperforming branch or team.", "**Why they ask:** they want evidence of turnaround leadership.\n\n**Answer (example):**\n\"I took over a branch with sagging morale, high wait times, and weak growth. I started by diagnosing — I watched the floor, listened to the team and customers, and found scheduling that ignored peaks and bankers unsure of expectations. I rescheduled to traffic, set clear quality-based goals, coached individually, and fixed the service pain points. Within a couple of quarters wait times dropped, satisfaction rose, and growth followed because the team was finally having good conversations instead of firefighting. The lesson was that performance problems are usually clarity and process problems, not people problems.\"\n\nTip: Diagnose first, fix process and clarity, coach individually — show performance following from a healthier operation.", "D", "S", null, {"f":["What's usually the real cause of an underperforming branch?","Often unclear expectations and broken processes — scheduling, service pain points, coaching gaps — rather than simply the wrong people."]}],
["Regulation", "What are check holds and how do you explain a deposit hold to a customer?", "**Why they ask:** funds-availability rules cause frequent customer friction.\n\n**Answer:**\n\"Banks can place a hold on deposited funds under funds-availability rules, so a check doesn't become available instantly in every case — larger deposits, new accounts, or certain checks can have longer holds while the deposit clears, which protects the customer and bank from returned-check losses. When a customer is frustrated, I explain plainly why the hold exists, exactly when the funds will be available, and whether any portion is available sooner. If they have an urgent need and a solid history, I check whether the hold can be reviewed. Clear, upfront communication about availability prevents a bounced payment and an angry return visit.\"\n\nTip: Holds under funds-availability rules protect against returned-check loss — explain the reason, the exact availability date, and any portion available sooner.", "D", "M", null, {"f":["Why hold a deposited check at all?","If the check is later returned unpaid, the bank and customer could lose funds already withdrawn — the hold ensures it clears before full availability."]}],
["Safety", "What's your approach to branch safety and security, including robbery protocols?", "**Why they ask:** branch safety is a real responsibility of the manager.\n\n**Answer:**\n\"Safety comes first — people over money, always. I make sure the team is trained on and follows security protocols: opening and closing procedures done safely, cash limits and timed access that reduce the incentive, and in a robbery, comply, stay calm, don't be a hero, observe what you safely can, and protect everyone present. Afterward, follow the bank's response plan and support the staff, who may be shaken. Day to day, I keep the branch secure with the required controls and make sure nobody cuts a safety corner for convenience. No amount of cash is worth a person's safety.\"\n\nTip: People over money — train on protocols, comply in a robbery, and never let anyone cut a safety corner for convenience.", "D", "M", null, {"f":["What's the rule for staff during a robbery?","Comply, stay calm, protect everyone's safety, and don't resist or play hero — then follow the response plan and support shaken staff afterward."]}],
["Service", "How do you serve a customer who is new to the country or new to banking with little credit history?", "**Why they ask:** inclusive service expands the branch and serves the community.\n\n**Answer:**\n\"I meet them where they are without condescension. Someone new to banking or to the country may not know the products or the jargon, so I explain things plainly, help them establish the basics — a checking and savings account, understanding fees, building a banking relationship — and look at products designed for building credit, like a secured card, so they can establish a history over time. I'm patient with questions and sensitive to language or cultural differences. Done well, I've helped a person get a real financial footing and started a relationship that can last decades as their needs grow.\"\n\nTip: Explain plainly without condescension, establish the basics, and use credit-building products like a secured card to help them build history.", "D", "M", null, {"f":["How can a thin-file customer start building credit?","A secured card or a credit-builder product lets them establish on-time payment history, which over time builds the score that unlocks mainstream credit."]}],
["Advice", "How do you explain overdraft protection options to a customer?", "**Why they ask:** overdraft is a sensitive, regulated, high-friction area.\n\n**Answer:**\n\"I lay out the choices honestly so the customer picks what fits. They can link a savings account or a line of credit to cover an overdraft, usually far cheaper than paying per-item overdraft fees; they can opt out of overdraft coverage on everyday debit transactions so those are simply declined instead of generating fees; or they can rely on low-balance alerts to avoid the situation entirely. I explain the real cost of each path rather than steering them to the most fee-generating one. For many customers, a linked savings account plus alerts is the cheapest, least stressful setup, and I'll say so.\"\n\nTip: Present linked savings/line-of-credit protection, the opt-out, and alerts honestly — the cheapest setup for most beats fee-generating coverage.", "D", "M", null, {"f":["What's often the cheapest overdraft setup?","Linking a savings account or line of credit to cover shortfalls, plus low-balance alerts — far cheaper than repeated per-item overdraft fees."]}],
["Compliance", "How do you protect customer privacy and sensitive information at the branch?", "**Why they ask:** data protection is both regulated and trust-critical.\n\n**Answer:**\n\"I treat customer information as something I'd never want mishandled if it were mine. Practically that means not discussing account details where others can overhear, verifying identity before releasing any information, keeping screens and documents out of view, securely disposing of anything with customer data, and never accessing accounts without a legitimate business reason — curiosity about a neighbor's or a celebrity's account is a firing offense for good reason. I also coach the team on phishing and social-engineering attempts to extract information. Privacy breaches destroy trust and carry real legal consequences, so the standard is zero shortcuts.\"\n\nTip: Verify before disclosing, keep info out of earshot and sight, access only with business need, and guard against social engineering.", "D", "M", null, {"f":["Why is accessing an account without business reason a serious violation?","It breaches customer privacy and trust and the law — looking up a neighbor's or celebrity's account out of curiosity is grounds for termination."]}],
["Service", "How do you handle a formal complaint or a customer threatening to go to a regulator?", "**Why they ask:** complaint handling affects both the customer and regulatory standing.\n\n**Answer:**\n\"I take it seriously and don't get defensive. I listen fully, acknowledge the issue, and own what we got wrong, then work to resolve it within my authority and the bank's complaint process — because a complaint resolved well often keeps a customer and surfaces a real problem worth fixing. I document it accurately, follow the escalation path, and never try to talk a customer out of their right to complain to a regulator; that right exists for a reason and stonewalling makes everything worse. Most people escalating just want to be heard and made whole, and handling it with genuine care usually resolves it.\"\n\nTip: Listen, own the error, resolve within process, document accurately, and never discourage a customer's right to escalate.", "D", "M", null, {"f":["Should you discourage a customer from contacting a regulator?","No — that right exists and stonewalling worsens it; resolve the issue genuinely, and most customers won't need to escalate if they feel heard."]}],
["Advice", "How do you talk with savers and borrowers when interest rates are moving?", "**Why they ask:** rate changes drive customer questions and opportunities.\n\n**Answer:**\n\"When rates rise, I proactively reach savers who have idle balances earning little and show them better options like higher-yield savings or CDs — it's genuine value and it retains deposits that might otherwise leave for a competitor's rate. For borrowers, rising rates make locking a fixed rate or acting sooner more relevant, while falling rates may open refinancing conversations. The key is being proactive and honest rather than letting customers discover on their own that their money sat idle. Rate moves are exactly when a good banker reaches out, because the customer's best move has changed and they may not realize it.\"\n\nTip: Proactively move idle savers to better-yielding products as rates rise, and raise fixed-rate or refi conversations with borrowers — honest, timely outreach.", "D", "M", null, {"f":["Why reach out to savers when rates rise?","Idle balances earning little are exactly what competitors target with higher rates — proactively offering better options delivers real value and retains the deposit."]}],
["Teamwork", "How do you get the teller line and the banker desks working as one team?", "**Why they ask:** branch performance depends on handoffs between roles.\n\n**Answer:**\n\"The teller line and bankers are one service team, and the handoff between them is where opportunities and problems live. I build the habit that tellers, who see customers most often, listen for needs and warmly introduce the customer to a banker — not a cold transfer, but 'let me introduce you to someone who can help with that.' Bankers in turn respect that the teller surfaced it and close the loop. I run quick huddles so everyone knows the day's focus, and I make sure recognition is shared, because if only bankers get credit for referrals the line stops making them. One team, shared wins.\"\n\nTip: Make the teller-to-banker handoff warm and shared-credit, run daily huddles, and treat both roles as one service team.", "D", "M", null, {"f":["Why share referral credit with the teller line?","Tellers see customers most and surface the needs; if only bankers get credit, the line stops referring — shared recognition keeps the pipeline flowing."]}],
["Reflection", "How do you measure your own success as a branch manager?", "**Why they ask:** they want to know what the candidate truly optimizes for.\n\n**Answer:**\n\"By a few things together, not one number. Healthy, sustainable growth in deposits and lending; strong customer satisfaction and retention; a team that's engaged, developing, and low in unwanted turnover; and clean operations and compliance with no control lapses. If growth is up but satisfaction and the team are suffering, I haven't succeeded, I've borrowed from the future. The branches I'm proudest of had strong results and a team that wanted to stay and customers who referred their friends — that combination is the real scoreboard, because it's what lasts.\"\n\nTip: Sustainable growth, satisfaction and retention, an engaged developing team, and clean compliance — all together, not growth alone.", "B", "S", null, {"f":["Why isn't growth alone a sufficient measure?","Growth bought by pushing products or burning out the team is borrowed from the future — lasting success pairs results with loyalty and a healthy team."]}],
["Identity", "How do you help a customer who's a victim of identity theft?", "**Why they ask:** identity theft response is a common, high-stress service moment.\n\n**Answer:**\n\"I move quickly and calmly, because the customer is scared. First, secure their accounts — flag or freeze what's compromised, reissue cards and credentials, and dispute unauthorized transactions through the proper process. Then I help them with the broader steps: reviewing recent activity together, setting up alerts, and pointing them to the official resources for reporting identity theft and placing fraud alerts or freezes on their credit. Throughout, I reassure them about the protections that exist and that we're handling it. People remember that their bank stood with them during a frightening experience; it's one of the strongest trust-builders there is.\"\n\nTip: Secure accounts fast (freeze, reissue, dispute), then guide them through alerts, credit freezes and official reporting — calm, hands-on help.", "D", "M", null, {"f":["What should a customer do beyond securing bank accounts?","Report the identity theft through the official channel, place fraud alerts or a freeze on their credit, and monitor their reports for further misuse."]}],
["Ethics", "It's the end of a quarter and you're short of goal. How do you lead the team?", "**Why they ask:** period-end pressure is exactly when sales ethics are tested.\n\n**Answer:**\n\"I lead the same way I do all quarter — toward genuine customer needs, not toward the number by any means. I'd rally the team to reach out to customers we can truly help, revisit conversations that stalled, and work the legitimate opportunities in the book harder. What I won't do is signal, even subtly, that we should open products customers don't want or pressure them to hit a figure, because that's how real harm and scandals happen, and a missed quarter is recoverable while a trust breach isn't. I'd rather explain a short month honestly than manufacture results I'd be ashamed of.\"\n\nTip: Work legitimate opportunities harder, never pressure unwanted products — a missed quarter is recoverable, a trust breach isn't.", "D", "S", null, {"t":1,"f":["Why not just push harder to make the number?","Pressuring unwanted products causes real customer harm and the kind of scandal that destroys a franchise — a short quarter is far cheaper than lost trust."]}],
["Closing", "Why do you want to work in retail banking and branch management?", "**Why they ask:** motivation and fit for a people-and-numbers role.\n\n**Answer:**\n\"I like that it combines running a real business — growth, operations, controls — with genuinely helping people at moments that matter: buying a home, starting a business, recovering from fraud, getting their finances on track. I enjoy developing a team and watching people grow into bigger roles, and I like being part of a community rather than behind a desk. It's a role where doing right by customers and running a strong business reinforce each other, and that alignment is what makes it satisfying to me rather than just a job.\"\n\nTip: Combines running a business with helping people at pivotal moments and developing a team — doing right and good business align.", "B", "M", null, {"f":["What part of the role energizes you most?","Pick an honest one — developing the team, helping customers at big life moments, or building the branch's local relationships — and say why."]}]
]);
